package io.xeros.solo;
import io.xeros.*;import io.xeros.content.bosses.*;import io.xeros.content.bosses.zulrah.Zulrah;import io.xeros.content.combat.*;import io.xeros.model.*;import io.xeros.model.cycleevent.*;import io.xeros.model.entity.npc.*;import io.xeros.model.entity.player.*;import io.xeros.model.entity.player.save.PlayerSave;import java.util.*;import java.lang.reflect.*;
public final class BossSpecialRoutesCheck {
 static void ok(boolean b,String s){BossesPlayableCheck.ok(b,s);}static Player actor(){return BossRoutesCheck.actor();}static void tick(Player p,int n){for(int i=0;i<n;i++){SkillsAuditCheck.tick(1);BossesPlayableCheck.applied(p);if(p.teleTimer>0)p.teleTimer--;}}
 static void savedAt(Player p,int x,int y){ok(PlayerSave.saveGameInstant(p),"Save special instance");Player q=AttackDefencePlayableCheck.actor();q.setLoginName("bossroutes63qa");ok(PlayerSave.loadGame(q,"bossroutes63qa","IsolatedAudit",true).toString().equals("SUCCESS")&&q.heightLevel==0&&q.getTeleportToX()==x&&q.getTeleportToY()==y,"Safe special relog");SkillsAuditCheck.clear(q);}
 static void vorkath()throws Exception{Player p=actor();BossRoutesCheck.at(p,2271,4052,0);Vorkath.enterInstance(p,1);tick(p,8);ok(p.heightLevel==4&&p.absY==4054,"Vorkath entry");NPC n=Arrays.stream(NPCHandler.npcs).filter(v->v!=null&&v.getNpcId()==8026&&v.spawnedBy==1&&v.heightLevel==4&&!v.isUnregister()).findFirst().orElseThrow();Vorkath.spawn(p);ok(Arrays.stream(NPCHandler.npcs).filter(v->v!=null&&v.getNpcId()==8026&&v.spawnedBy==1&&v.heightLevel==4&&!v.isUnregister()).count()==1,"Duplicate Vorkath");tick(p,5);Vorkath.poke(p,n);tick(p,7);ok(n.getNpcId()==8028,"Vorkath wake id="+n.getNpcId()+" pos="+p.absX+","+p.absY+","+p.heightLevel+" interact="+p.getUtilityMagic().canInteract());savedAt(p,2272,4050);Field event=Vorkath.class.getDeclaredField("attackType");event.setAccessible(true);Class<?> type=event.getType();event.set(p.getVorkath(),Enum.valueOf((Class)type,"MAGIC"));java.lang.reflect.Method m=Vorkath.class.getDeclaredMethod("handleAttackType");m.setAccessible(true);CycleEvent pending=(CycleEvent)m.invoke(p.getVorkath());Object lock=new Object();CycleEventHandler.getSingleton().addEvent(lock,pending,1);int hp=p.getHealth().getCurrentHealth();BossRoutesCheck.at(p,2273,4054,4);Vorkath.exit(p);tick(p,10);ok(p.heightLevel==0&&p.absY==4052&&n.isUnregister()&&p.getHealth().getCurrentHealth()==hp,"Vorkath exit/delayed hit");Vorkath.spawn(p);ok(Arrays.stream(NPCHandler.npcs).noneMatch(v->v!=null&&v.spawnedBy==1&&v.getNpcId()==8026&&!v.isUnregister()),"Vorkath respawn after exit");n.processDeregistration();BossesPlayableCheck.clear(p);System.out.println("BOSSES_VORKATH_REAL_ENTRY_UNIQUE_SPAWN_WAKE_ONCE_EXIT_DELAYED_ATTACK_CANCEL_AND_SAFE_SAVE_RELOAD_PASS");
 }
 static void zulrah(){Player p=actor();Zulrah z=p.getZulrahEvent();z.initialize();Object arena=z.getInstancedZulrah();z.initialize();ok(z.getInstancedZulrah()==arena,"Duplicate Zulrah startup");tick(p,12);ok(p.getInstance()==arena&&z.getNpc()!=null&&z.getNpc().getNpcId()==2042,"Zulrah spawn");savedAt(p,2203,3056);NPC npc=z.getNpc();z.changeStage(2,CombatType.MELEE,io.xeros.content.bosses.zulrah.ZulrahLocation.NORTH);p.getInstance().remove(p);BossRoutesCheck.at(p,3101,3509,0);tick(p,10);ok(!z.isActive()&&!z.isTransforming()&&z.getInstancedZulrah()==null&&npc.isUnregister(),"Zulrah exit events not cancelled");BossesPlayableCheck.clear(p);p=actor();p.isDead=true;p.getZulrahEvent().initialize();ok(p.getZulrahEvent().getInstancedZulrah()==null,"Dead Zulrah entry");BossesPlayableCheck.clear(p);System.out.println("BOSSES_ZULRAH_STARTUP_DUPLICATE_REAL_SPAWN_TRANSFORM_EXIT_CANCEL_SAFE_SAVE_RELOAD_AND_DEAD_GUARD_PASS");}
 static void processor(){NPC[] previous=NPCHandler.npcs;try{NPCHandler.npcs=new NPC[NPCHandler.maxNPCs];NPC a=new NPC(1,2805,io.xeros.model.definitions.NpcDef.forId(2805));final int[] hits={0};NPC b=new NPC(2,2805,io.xeros.model.definitions.NpcDef.forId(2805)){public void process(){hits[0]++;}};NPCHandler.npcs[1]=a;NPCHandler.npcs[2]=b;a.unregister();Server.npcHandler.process();ok(NPCHandler.npcs[1]==null&&hits[0]==1,"NPC removal skipped remaining NPCs");}finally{NPCHandler.npcs=previous;}Player p=actor();p.mapRegionX=0;p.mapRegionY=0;ok(!PathFinder.getPathFinder().accessable(p,3200,3200),"Out of local map route did not reject");BossesPlayableCheck.clear(p);System.out.println("BOSSES_NPC_REMOVAL_CONTINUES_PROCESSING_AND_OUT_OF_LOCAL_MAP_PATH_GUARD_PASS");}
 public static void main(String[]a)throws Exception{Thread.setDefaultUncaughtExceptionHandler((t,e)->{e.printStackTrace();System.exit(1);});Thread.currentThread().setName("GameThread");System.setProperty("solo.mode","true");System.setProperty("solo.xp","1");Server.startServerless();Configuration.BONUS_SKILL=-1;vorkath();zulrah();processor();System.out.println("BOSSES_SPECIAL_ROUTES_V63_PASS");System.exit(0);}
}
